grant references on table "public"."LLMs" to "anon";

grant select on table "public"."LLMs" to "anon";

grant trigger on table "public"."LLMs" to "anon";

grant truncate on table "public"."LLMs" to "anon";

grant update on table "public"."LLMs" to "anon";

